module restore_array (\n    input clk,\n    input rst_n,\n    input start,\n    input load,\n    input [31:0] data_in,\n    output reg [31:0] array_out_0,\n    output reg [31:0] array_out_1,\n    output reg [31:0] array_out_2,\n    output reg [31:0] array_out_3,\n    output reg [31:0] array_out_4,\n    output reg [31:0] array_out_5,\n    output reg [31:0] array_out_6,\n    output reg [31:0] array_out_7,\n    output reg done\n);\n\n    parameter N = 8'd8;\n    parameter MEM_SIZE = 6'd64;\n\n    // State declarations\n    localparam [3:0] IDLE      = 4'd0;\n    localparam [3:0] READ1     = 4'd1;\n    localparam [3:0] READ2     = 4'd2;\n    localparam [3:0] READ3     = 4'd3;\n    localparam [3:0] MULT      = 4'd4;\n    localparam [3:0] DIV       = 4'd5;\n    localparam [3:0] SQRT_START= 4'd6;\n    localparam [3:0] SQRT_LOOP = 4'd7;\n    localparam [3:0] SQRT_DONE = 4'd8;\n    localparam [3:0] DONE_STATE= 4'd9;\n\n    reg [31:0] mem [0:63];\n    reg [5:0] load_counter;\n\n    reg [3:0] state;\n    reg [3:0] i;\n    reg [3:0] j, k;\n    reg [31:0] A, B, C;\n    reg [63:0] product;\n    reg [63:0] quotient;\n    reg [31:0] sqrt_val;\n    reg [5:0] bit_index;\n    reg [5:0] address;\n\n    wire [31:0] data_out;\n    assign data_out = mem[address];\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            load_counter <= 6'd0;\n            state <= IDLE;\n            done <= 1'b0;\n            i <= 4'd0;\n            array_out_0 <= 32'd0;\n            array_out_1 <= 32'd0;\n            array_out_2 <= 32'd0;\n            array_out_3 <= 32'd0;\n            array_out_4 <= 32'd0;\n            array_out_5 <= 32'd0;\n            array_out_6 <= 32'd0;\n            array_out_7 <= 32'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        i <= 4'd0;\n                        state <= READ1;\n                    end\n                end\n                \n                READ1: begin\n                    j <= (i + 4'd1) % N;\n                    k <= (i + 4'd2) % N;\n                    address <= i * N + ((i + 4'd1) % N);\n                    state <= READ2;\n                end\n                \n                READ2: begin\n                    A <= data_out;\n                    address <= i * N + ((i + 4'd2) % N);\n                    state <= READ3;\n                end\n                \n                READ3: begin\n                    B <= data_out;\n                    address <= j * N + k;\n                    state <= MULT;\n                end\n                \n                MULT: begin\n                    C <= data_out;\n                    product <= A * B;\n                    state <= DIV;\n                end\n                \n                DIV: begin\n                    quotient <= product / C;\n                    state <= SQRT_START;\n                end\n                \n                SQRT_START: begin\n                    sqrt_val <= 32'd0;\n                    bit_index <= 6'd31;\n                    state <= SQRT_LOOP;\n                end\n                \n                SQRT_LOOP: begin\n                    if ((sqrt_val + (32'd1 << bit_index)) * (sqrt_val + (32'd1 << bit_index)) <= quotient) begin\n                        sqrt_val <= sqrt_val + (32'd1 << bit_index);\n                    end\n                    if (bit_index == 6'd0) begin\n                        state <= SQRT_DONE;\n                    end else begin\n                        bit_index <= bit_index - 6'd1;\n                    end\n                end\n                \n                SQRT_DONE: begin\n                    case (i)\n                        4'd0: array_out_0 <= sqrt_val;\n                        4'd1: array_out_1 <= sqrt_val;\n                        4'd2: array_out_2 <= sqrt_val;\n                        4'd3: array_out_3 <= sqrt_val;\n                        4'd4: array_out_4 <= sqrt_val;\n                        4'd5: array_out_5 <= sqrt_val;\n                        4'd6: array_out_6 <= sqrt_val;\n                        4'd7: array_out_7 <= sqrt_val;\n                    endcase\n                    i <= i + 4'd1;\n                    if (i < (N-4'd1)) state <= READ1;\n                    else begin\n                        state <= DONE_STATE;\n                        done <= 1'b1;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    // Maintain done until reset or new start\n                end\n                \n                default: state <= IDLE;\n            endcase\n\n            if (load) begin\n                if (load_counter < MEM_SIZE) begin\n                    mem[load_counter] <= data_in;\n                    load_counter <= load_counter + 6'd1;\n                end\n            end\n        end\n    end\nendmodule